//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.vScrenID = "ULDBNS25102.xml";
scwin.vMktactCd = "";
scwin.vBndApplId = "";
scwin.vBndListProcsTpCd = "2";
scwin.vStdCd = '';
scwin.vStrtDd = '';
scwin.vRowCount = 0;
scwin.processGp;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_SearchIsuInfo
 * 설명       : 종목정보를 조회한다.
 ***********************************************/
scwin.fn_SearchIsuInfo = function() {
    var param = '';
    param += "&{P}V_STD_CD=" + scwin.vStdCd;
    param += "&{P}V_STRT_DD=" + scwin.vStrtDd;
    //param += "&{P}V_STD_CD=KR6015861S58";
    //param += "&{P}V_STRT_DD="+ vStrtDd;

    //종목정보
    var dsNm = 'BNS_ISU_INFO';
    var qryId = 'lds.stf.bnscommon.select.readBndIsuInfo';
    dts_IsuInfo.SyncLoad = true;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_IsuInfo, dsNm, qryId, param);
    if (dts_IsuInfo.getTotalRow() > 0) {
        $c.stf.setObjectValue(txb_AmtHan, $c.bns.fn_ChgAmtToHan(dts_IsuInfo.getCellData(1, 'LIST_AMT')));
    }

    //신용평가정보
    dsNm = 'BNS_CREDIT_INFO';
    qryId = 'lds.stf.bnscommon.select.listBndCredit';
    dts_Credit.SyncLoad = true;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_Credit, dsNm, qryId, param);
    if (dts_Credit.getTotalRow() > 0) {
        scwin.fn_SetCreditData();
    }

    //인수기관정보
    dsNm = 'BNS_UDWRT_INST';
    qryId = 'lds.stf.bnscommon.select.listBndUdwrtInst';
    dts_UdwrtInst.SyncLoad = true;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_UdwrtInst, dsNm, qryId, param);
    if (dts_UdwrtInst.getTotalRow() > 0) {
        scwin.fn_SetUdwrtInstData();
    }

    //원리금정보
    dsNm = 'BNS_PRINCINT_INFO';
    qryId = 'lds.stf.bnscommon.select.listBndPrincint';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_Princint, dsNm, qryId, param);

    //CALL
    dsNm = 'BNS_OPTION_CALL';
    qryId = 'lds.stf.bnscommon.select.listBndOptionCall';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_OptionCall, dsNm, qryId, param);

    //PUT
    dsNm = 'BNS_OPTION_PUT';
    qryId = 'lds.stf.bnscommon.select.listBndOptionPut';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_OptionPut, dsNm, qryId, param);

    //변동금리
    dsNm = 'BNS_CHG_INT';
    qryId = 'lds.stf.bnscommon.select.listBndChgInt';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_ChgInt, dsNm, qryId, param);

    //분할상환
    dsNm = 'BNS_SPLIT_REDMPT';
    qryId = 'lds.stf.bnscommon.select.listBndSplitRedmpt';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_SplitRedmpt, dsNm, qryId, param);

    //주식관련 행사가격 조정 JACKAL_190220
    dsNm = 'BNS_STOCK_REL_EXECPRC_ADJ';
    qryId = 'lds.stf.bnscommon.select.listBndStockRelExerPrcAdj';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_StockRel, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_SetUdwrtInstData
 * 설명       : 인수기관 정보를 설정한다.
 ***********************************************/
scwin.fn_SetUdwrtInstData = function() {
    $c.stf.setObjectValue(cmb_BndUdwrtInstCd1, '0');
    $c.stf.setObjectValue(edt_UdwrtAmt1, '');
    $c.stf.setObjectValue(cmb_BndUdwrtInstCd2, '0');
    $c.stf.setObjectValue(edt_UdwrtAmt2, '');
    $c.stf.setObjectValue(cmb_BndUdwrtInstCd3, '0');
    $c.stf.setObjectValue(edt_UdwrtAmt3, '');
    $c.stf.setObjectValue(cmb_BndUdwrtInstCd4, '0');
    $c.stf.setObjectValue(edt_UdwrtAmt4, '');
    $c.stf.setObjectValue(edt_UdwrtAmt5, '');
    if (dts_UdwrtInst.getTotalRow() >= 1) {
        scwin.fn_SetUdwrtInst(1, cmb_BndUdwrtInstCd1, edt_UdwrtAmt1);
    }
    if (dts_UdwrtInst.getTotalRow() >= 2) {
        scwin.fn_SetUdwrtInst(2, cmb_BndUdwrtInstCd2, edt_UdwrtAmt2);
    }
    if (dts_UdwrtInst.getTotalRow() >= 3) {
        scwin.fn_SetUdwrtInst(3, cmb_BndUdwrtInstCd3, edt_UdwrtAmt3);
    }
    if (dts_UdwrtInst.getTotalRow() >= 4) {
        scwin.fn_SetUdwrtInst(4, cmb_BndUdwrtInstCd4, edt_UdwrtAmt4);
    }
    if (dts_UdwrtInst.getTotalRow() >= 5) {
        $c.stf.setObjectValue(edt_UdwrtAmt5, dts_UdwrtInst.getCellData(5, 'UDWRT_AMT'));
    }
};



/********************************************** 
 * 함수명   : fn_SetCreditData
 * 설명       : 신용평가 정보를 설정한다.
 ***********************************************/
scwin.fn_SetCreditData = function() {
    $c.stf.setObjectValue(cmb_CreditValuInstCd1, '0');
    $c.stf.setObjectValue(cmb_ByinstCreditValuGrd1, '0');
    $c.stf.setObjectValue(cmb_SfValuYn1, '');
    $c.stf.setObjectValue(cmb_CreditValuInstCd2, '0');
    $c.stf.setObjectValue(cmb_ByinstCreditValuGrd2, '0');
    $c.stf.setObjectValue(cmb_SfValuYn2, '');
    $c.stf.setObjectValue(cmb_CreditValuInstCd3, '0');
    $c.stf.setObjectValue(cmb_ByinstCreditValuGrd3, '0');
    $c.stf.setObjectValue(cmb_SfValuYn3, '');
    $c.stf.setObjectValue(cmb_CreditValuInstCd4, '0');
    $c.stf.setObjectValue(cmb_ByinstCreditValuGrd4, '0');
    $c.stf.setObjectValue(cmb_SfValuYn4, '');
    if (dts_Credit.getTotalRow() > 0) {
        for (var idx = 1; idx <= dts_Credit.getTotalRow(); idx++) {
            if (dts_Credit.getCellData(idx, 'CREDIT_VALU_INST_CD') == '9201') {
                $c.stf.setObjectValue(cmb_CreditValuInstCd1, dts_Credit.getCellData(idx, "CREDIT_VALU_INST_CD"));
                $c.stf.setObjectValue(cmb_ByinstCreditValuGrd1, dts_Credit.getCellData(idx, "BYINST_CREDIT_VALU_GRD"));
                $c.stf.setObjectValue(cmb_SfValuYn1, dts_Credit.getCellData(idx, "SF_VALU_YN"));
            } else if (dts_Credit.getCellData(idx, 'CREDIT_VALU_INST_CD') == '9202') {
                $c.stf.setObjectValue(cmb_CreditValuInstCd2, dts_Credit.getCellData(idx, "CREDIT_VALU_INST_CD"));
                $c.stf.setObjectValue(cmb_ByinstCreditValuGrd2, dts_Credit.getCellData(idx, "BYINST_CREDIT_VALU_GRD"));
                $c.stf.setObjectValue(cmb_SfValuYn2, dts_Credit.getCellData(idx, "SF_VALU_YN"));
            } else if (dts_Credit.getCellData(idx, 'CREDIT_VALU_INST_CD') == '9203') {
                $c.stf.setObjectValue(cmb_CreditValuInstCd3, dts_Credit.getCellData(idx, "CREDIT_VALU_INST_CD"));
                $c.stf.setObjectValue(cmb_ByinstCreditValuGrd3, dts_Credit.getCellData(idx, "BYINST_CREDIT_VALU_GRD"));
                $c.stf.setObjectValue(cmb_SfValuYn3, dts_Credit.getCellData(idx, "SF_VALU_YN"));
            } else if (dts_Credit.getCellData(idx, 'CREDIT_VALU_INST_CD') == '9204') {
                $c.stf.setObjectValue(cmb_CreditValuInstCd4, dts_Credit.getCellData(idx, "CREDIT_VALU_INST_CD"));
                $c.stf.setObjectValue(cmb_ByinstCreditValuGrd4, dts_Credit.getCellData(idx, "BYINST_CREDIT_VALU_GRD"));
                $c.stf.setObjectValue(cmb_SfValuYn4, dts_Credit.getCellData(idx, "SF_VALU_YN"));
            }
        }
    }
};





/********************************************** 
 * 함수명   : fn_SearchMktact
 * 설명       : 시장조치내역 조회한다.
 ***********************************************/
scwin.fn_SearchMktact = function() {
    var param = '';
    param += "&{P}V_STD_CD=" + scwin.vStdCd;
    //param += "&{P}V_STD_CD=KR6015861S58";

    var dsNm = 'BNS_MKTACT_DTL';
    var qryId = 'lds.stf.bnscommon.select.listMktactDtl';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_SetComboCode
 * 설명       : 콤보데이터를 정의한다.
 ***********************************************/
scwin.fn_SetComboCode = function() {
    //기관코드
    var qryId = 'lds.stf.bnscommon.select.listInstCd';
    var dsNm = 'BNS_INST_INFO';
    var param = '&{P}V_INST_NM=';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_InstCd, dsNm, qryId, param);

    //표면이자율결정 기준금리
    $c.bns.fn_SetBnsCombo(scwin.vScrenID, dts_CoupntRtCd, '03050');

    //공통콤보
    var arrCid = [];
    arrCid.push({
        cid: '02475',
