    }); //이자일지급구분			
    arrCid.push({
        cid: '03512',
        cnm: 'cmb_IntUdwonProcsCd'
    }); //이자원단위 미만처리		
    arrCid.push({
        cid: '03114',
        cnm: 'cmb_BndOddllotddIntBasTpCd'
