scwin.grd_List_OnClick = function(row, colid) {
    if (colid == 'BND_MKTACT_TP_NM') {
        if (dts_List.getCellData(row, 'BND_MKTACT_TP_CD') == 'C') {
            $c.win.alert('신용평가수신은 상세화면이 없습니다.');
            return;
        } else {
            scwin.fn_GetPar = fn_GetParMktactDtl;
            $c.bns.fn_PopClsProcesStatIsuInfo(dts_List.getCellData(row, 'BND_MKTACT_TP_CD'));
        }
    }
};
