scwin.cmb_IntRtDecsnMiscBasIntCd_OnKillFocus = function() {
    //이자지급방법이 변동금리형
    var cd = $c.stf.getObjectValue(cmb_IntPayMethdCd);
    if (cd > 20) {
        //표면이자율 변경
        $c.stf.setObjectValue(cmb_CoupnRtDecsnBasIntCd, $c.stf.getObjectValue(cmb_IntRtDecsnMiscBasIntCd));
        //기타를 선택하면
        if ($c.stf.getObjectValue(cmb_IntRtDecsnMiscBasIntCd) == '90') {
            txb_CoupnRtMiscBasIntContn.setDisabled(false);
            txb_IntRtDecsnMiscBasIntNm.setDisabled(false);
        } else {
            $c.stf.setObjectValue(txb_CoupnRtMiscBasIntContn, '');
            $c.stf.setObjectValue(txb_IntRtDecsnMiscBasIntNm, '');
            txb_CoupnRtMiscBasIntContn.setDisabled(true);
            txb_IntRtDecsnMiscBasIntNm.setDisabled(true);
        }
    }
};
