scwin.cmb_IntDecsnRegulYn_OnSelChange = function() {
    // JACKAL_190509
    //alert('cmb_IntDecsnRegulYn.OnSelChange()');

    var cd = $c.stf.getObjectValue(cmb_IntDecsnRegulYn);
    // 행사가격 조정 해당사항이면 
    if (cd == 'Y') {
        txb_IntDecsnNregulRsnContn.setDisabled(true);
        $c.stf.setObjectValue(txb_IntDecsnNregulRsnContn, '');
    } else {
        txb_IntDecsnNregulRsnContn.setDisabled(false);
    }
};
